export function listeningN1PageSrc(page: number) {
	return `/listening/n1/pages/${String(page).padStart(3, "0")}.jpg`;
}

export function listeningN1TrackSrc(disc: ListeningN1Disc, track: number) {
	const prefix = disc === "cd1" ? "CD01" : "CD02";
	return `/audio/n1/${disc}/${prefix}_${String(track).padStart(2, "0")}.mp3`;
}

