export function listeningN1BookChapters(): readonly ListeningN1Chapter[] {
	return listeningN1Chapters;
}

export function findListeningN1Chapter(chapter: number) {
	return listeningN1Chapters.find((item) => item.number === chapter);
}

export function findListeningN1Section(chapter: number, section: number) {
	return findListeningN1Chapter(chapter)?.sections.find((item) => item.number === section);
}

export function listeningN1SectionDisc(chapter: number, section: number): ListeningN1Disc {
	return findListeningN1Section(chapter, section)?.disc ?? "cd1";
}
